"""Presentación HTML local. Texto y cifras se derivan de los reportes cerrados."""
import json
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[3];PERF=ROOT/'tests/performance'
def table(h,rs):return '<div class="scroll"><table><tr>'+''.join('<th>'+str(x)+'</th>'for x in h)+'</tr>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>'for x in r)+'</tr>'for r in rs)+'</table></div>'
def p(s):return '<p>'+s+'</p>'
def command(a):return '<div class="cmd"><button class="copy">Copiar</button><pre><code>'+escape("Set-Location 'C:\\Users\\Franco\\qolqe-g4-qa'\npowershell -NoProfile -ExecutionPolicy Bypass -File scripts/performance.ps1 "+a)+'</code></pre></div>'
def fmt(v):return 'sin muestra'if v is None else f'{v:.2f}'if isinstance(v,float)else str(v)
def main():
 results=json.loads((PERF/'resultados/resumen-entrega.json').read_text(encoding='utf-8'));by={r['profile']:r for r in results};primary=[by[k]for k in ['carga','campana','estres']if k in by]
 slides=[]
 def add(title,text,label='QUINCENA QOLQE · PARTE 3'):slides.append((title,text,label))
 add('¿Qolqe soporta la campaña de quincena?', '<div class="lead">Pruebas de rendimiento · Granit y Franco · Grupo 4</div>'+p('Se evalúa la capacidad de Qolqe Wallet frente a la demanda normal y la campaña. El trabajo combina un modelo de carga derivado del negocio, medición de recursos y conciliación de operaciones monetarias.')+p('Las conclusiones corresponden al entorno local medido. El código original de la aplicación se conserva intacto y las limitaciones se registran junto a cada resultado.'),'APERTURA · 0:00–0:40')
 add('El requerimiento define qué comprobar',p('En hora punta se inician 3000 sesiones por hora. Cada sesión dura en promedio dos minutos y realiza seis operaciones. La campaña triplica los usuarios simultáneos durante quince minutos y concentra inicios en los primeros cinco.')+table(['Condición','Criterio'],[['Consultas e inicio de sesión','p95 menor que 800 ms'],['Transferencias, recargas y pagos','p95 menor que 1500 ms'],['Hora punta','Como máximo 1% de errores y sin acumular retrasos'],['Campaña','Ninguna operación monetaria parcial ni duplicada']])+p('“Degradación razonable” no define un umbral numérico de campaña. Se informa esa ambigüedad y se compara con la referencia normal sin inventar un SLA.'),'NEGOCIO · 0:40–1:30')
 add('Se seleccionó k6 para generar carga por HTTP',p('k6 permite definir escenarios como código, aplicar etiquetas por operación y conservar métricas y umbrales. Se eligió por su integración con scripts versionados y su cercanía con JavaScript/TypeScript ya usado por el equipo.')+table(['Alternativa','Ventaja','Decisión en este proyecto'],[['k6','Escenarios, métricas y umbrales mediante scripts','Generador seleccionado; recursos con psutil'],['Locust','Modelado con Python y usuarios programables','Alternativa válida; también requeriría conciliación y monitoreo'],['JMeter','Diseño visual y ecosistema de reportes','La carga se ejecuta por consola; se prefirió un script compacto']])+p('La comparación es de adecuación al proyecto, no un benchmark entre herramientas. Se mide la API real; el renderizado del navegador no forma parte de esta prueba.'),'HERRAMIENTA · 1:30–2:30')
 add('Los flujos se priorizan por frecuencia y riesgo',table(['Operación','Peso','Justificación'],[['Saldo y perfil','30%','Acceso frecuente a información de cuenta'],['Movimientos','15%','Consulta de historial y confirmación de operaciones'],['Transferencias','15%','Movimiento directo de dinero'],['Contactos','10%','Consulta y búsqueda usadas en transferencias'],['Recargas','10%','Débito y emisión de comprobante'],['Consulta de deudas','6%','Consulta previa al pago'],['Pagos','4%','Débito y cancelación de una deuda'],['Otros','10%','Límites, alertas, solicitudes, dispositivos y sesiones']])+p('Las ponderaciones se aplican a operaciones de negocio. Saldo y perfil agrupa dos peticiones HTTP; login se mide por separado. El reporte conserva la mezcla realmente obtenida.'),'ALCANCE · 2:30–3:15')
 add('El modelo parte de los datos del negocio',table(['Parámetro','Derivación'],[['Concurrencia normal','3000/60 × 2 = aproximadamente 100 usuarios'],['Concurrencia de campaña','100 × 3 = aproximadamente 300 usuarios'],['Volumen normal','3000 × 6 / 3600 = 5 operaciones/s, además de login'],['Pausas','10–25 s; triangular con moda 19 s para media 18 s'],['Sesión','Un login y seis operaciones; no se fuerza a durar exactamente 120 s']])+p('La duración de sesión de dos minutos es una media de negocio. Bajo degradación, las sesiones pueden durar más. Los percentiles y el throughput se miden en ventanas estables y las diferencias se registran.'),'MODELO · 3:15–4:15')
 add('Carga, campaña y estrés se ejecutan por separado',table(['Perfil','Configuración','Objetivo'],[['Referencia','1 usuario','Validar scripts y obtener una referencia sin carga'],['Carga','Subida 300 s → 100 VUs; 600 s estable; descenso 60 s','Comprobar el horario punta'],['Campaña','Subida 300 s → 300 VUs; 600 s estable; descenso 60 s','Representar quince minutos con concentración inicial'],['Estrés','25 → 50 → 100 → 200 → 300 → 450 → 600 VUs; 150 s estables por escalón','Localizar incumplimiento observado']])+p('Las rampas de cinco minutos de campaña provienen del requerimiento. Las duraciones estables de carga y los escalones de estrés son decisiones experimentales justificadas. Las sesiones pueden finalizar durante una gracia adicional de hasta 150 s.'),'ESCENARIOS · 4:15–5:00')
 add('Datos independientes evitan falsos fallos de rendimiento',p('Cada VU tiene credenciales exclusivas, un destinatario y saldo inicial suficiente. Se generan mil movimientos de historial por propietario, contactos y deudas pendientes suficientes. Las consultas de deudas usan una deuda reservada que no se consume en pagos.')+p('Las transferencias y pagos utilizan S/1; las recargas S/5 y números distintos. Esto reduce el riesgo de agotar saldo, límites diarios o recargas por número. La preparación ocurre antes de la medición y no se modifican saldos durante la carga.')+p('El esquema y la lógica pertenecen al Qolqe original. Las bases de ejecución son exclusivas; el reinicio no afecta la base habitual de la demo funcional.')+'<aside>Un rechazo por regla de negocio se conserva y se investiga. No se etiqueta automáticamente como lentitud ni se excluye silenciosamente del reporte.</aside>','DATOS · 5:00–5:45')
 add('Los umbrales se evalúan junto con la integridad',p('Se calculan percentiles por operación para que un endpoint lento no quede oculto por otros rápidos. Se compara el volumen completado con la demanda normal y se registran errores HTTP, de transporte y de datos.')+p('La verificación monetaria relaciona cada intento con su respuesta, registro de operación, movimientos y saldos finales de propietario y destinatario. Un timeout no demuestra que la operación no se haya aplicado: se consulta la evidencia persistida.')+p('No se reintentan automáticamente escrituras de dinero. Una operación parcial o duplicada impide concluir cumplimiento de la campaña, incluso si era un defecto conocido de una entrega anterior.'),'ACEPTACIÓN · 5:45–6:30')
 add('CPU y memoria se miden en ambos procesos',p('El monitor registra cada segundo CPU y memoria de Qolqe y de k6. En Windows se incluye el proceso hijo de Python donde se ejecuta la aplicación. Las marcas de tiempo permiten cruzar recursos con latencia, errores y throughput.')+p('La CPU se conserva en equivalentes de núcleo y normalizada al total de procesadores. RSS se expresa en MB. Se registra también el estado del host para reconocer competencia de otros procesos.')+p('Si el generador supera aproximadamente 80% de CPU total, la corrida se considera inválida. Una ejecución válida puede incumplir el SLA del producto. La laptop compartida no certifica capacidad de producción.'),'ENTORNO · 6:30–7:00')
 add('Demostración en vivo con un perfil breve',p('La demo ejecuta el mismo flujo y conserva las pausas reales con cinco usuarios. Sirve para observar cómo se generan operaciones, recursos y evidencias. Los experimentos completos ya están conservados y se abren después.')+command('demo')+command('open')+p('Mientras corre, se explica la estructura: scripts/performance.ps1 inicia el ejecutor; tests/performance/escenarios/carga.js define las acciones; configuracion/modelo.json define la carga; scripts/performance.py prepara, monitorea y concilia.')+p('El perfil breve no reemplaza la carga de 100 VUs ni el estrés completo. Puede iniciarse antes de esta sección para consultar su reporte sin consumir todo el tiempo de exposición.'),'DEMO · 7:00–9:00')
 rows=[]
 for r in primary:
  w=r['windows'][0];rows.append([r['profile'],str(r['valid']),str(r['approved']),fmt(w['ops_s']),fmt(w['p95_consulta']),fmt(w['p95_dinero']),fmt(100*w['error_rate'])if w['error_rate']is not None else'—',str(r['integrity']['approved'])])
 add('Resultados observados en el entorno local',table(['Perfil','Válida','Cumple','Ops/s','p95 consulta ms','p95 dinero ms','Error %','Integridad'],rows)+p('La tabla utiliza la primera ventana estable de cada perfil; estrés tiene varias ventanas que se revisan en su reporte. Los percentiles agregados orientan y los resultados por endpoint determinan el cumplimiento temporal.')+'<p><a target="_blank" href="../../tests/performance/resultados/index.html">Abrir todos los reportes</a> · <a target="_blank" href="../../docs/parte3/Informe_Rendimiento_Qolqe.docx">Informe según plantilla</a></p>','RESULTADOS · 9:00–10:00')
 for profile,title in [('carga','Hora punta: resultado y evolución'),('campana','Campaña: respuesta e integridad'),('estres','Estrés: dónde dejó de cumplir')]:
  r=by.get(profile)
  if not r:continue
  base='../../tests/performance/resultados/'+r['meta']['run_id']
  breaches=[[op,fmt(v['p95']),1500 if op in ['transferencias','recargas','pagos']else 800]for op,v in r['by_operation'].items()if v['p95']>=(1500 if op in ['transferencias','recargas','pagos']else 800)]
  detail=table(['Operación que supera el umbral normal','p95 ms','Límite ms'],breaches)if breaches else p('Los p95 por operación de las ventanas analizadas están dentro de la referencia temporal normal.')
  add(title,p(f"Ejecución {r['meta']['run_id']}. Validez del experimento: {r['valid']}; cumplimiento del perfil: {r['approved']}; integridad: {r['integrity']['approved']}.")+detail+f'<img alt="Evolución de latencia, errores, throughput, usuarios y recursos" src="{base}/graficos/evolucion.png">'+p(f'<a target="_blank" href="{base}/reporte.html">Abrir reporte de esta corrida</a> · <a target="_blank" href="{base}/integridad.json">Conciliación</a> · <a target="_blank" href="{base}/recursos.csv">Recursos CSV</a>'),'EVIDENCIA · 10:00–12:30')
 diagnosis=json.loads((PERF/'resultados/diagnostico-sql.json').read_text(encoding='utf-8'))if(PERF/'resultados/diagnostico-sql.json').exists()else None
 diagtext=''
 if diagnosis:
  diagtext=table(['Movimientos en historial','Consultas SELECT','Consultas SUM','Mediana ms (diagnóstico directo)'],[[r['historial'],r['selects'],r['sumas'],fmt(r['mediana_ms'])]for r in diagnosis['summary']])+p('El patrón N+1 del historial está confirmado: una consulta adicional por movimiento antes de paginar. En estrés también se registran bloqueos de SQLite durante escrituras. Son focos distintos; no se atribuyen todos los bloqueos al N+1.')+'<p><a target="_blank" href="../../tests/performance/resultados/diagnostico-sql.json">Abrir diagnóstico SQL</a></p>'
 add('Diagnóstico y límites de las conclusiones',diagtext+p('El análisis sigue cuatro preguntas: ¿cumplió los umbrales?, ¿en qué operación y nivel falló?, ¿qué evidencia explica el comportamiento?, ¿qué acción corresponde? Se contrastan gráficos, recursos y logs.')+p('CPU alta, throughput estancado, esperas o errores de base de datos son pistas. No se midió directamente la espera de bloqueos ni la latencia de disco: una atribución a esos recursos se presenta como hipótesis hasta instrumentarlos.')+p('La capacidad se informa como el mayor nivel observado que cumple, con el volumen correspondiente y tamaños de muestra. No se extrapola a producción. Se recomienda repetir cerca del primer incumplimiento en un entorno dedicado.'),'ANÁLISIS · 12:30–13:30')
 stress=by.get('estres')
 if stress:
  levels=[25,50,100,200,300,450,600];rows=[]
  for level,w in zip(levels,stress['windows']):rows.append([level,fmt(w['ops_s']),fmt(w['by_operation'].get('movimientos',{}).get('p95')),fmt(100*w['error_rate'])if w['error_rate']is not None else '—','Sí'if w.get('per_operation_ok')and w['ops_s']>=level*.05 else 'No'])
  add('Capacidad observada y riesgo de respuestas perdidas',table(['VUs','Operaciones correctas/s','p95 movimientos ms','Error negocio %','Cumple referencia y volumen'],rows)+p('El límite se acota entre el mayor nivel observado que cumple y el siguiente probado que no cumple. Las ventanas de estrés son breves y el entorno compartido: no se certifica un máximo universal.')+p(f"En estrés se conciliaron {stress['integrity']['committed_after_http_error']} operaciones persistidas aunque el cliente recibiera error o perdiera la respuesta. No se detectaron duplicados o operaciones parciales, pero existe riesgo de repetición manual. Se recomienda consulta de estado e idempotencia; esas mejoras no se implementaron en Qolqe."),'ANÁLISIS · RESPALDO')
 add('Resistencia, recomendaciones y cierre',p('La operación de 6:00 a 24:00 hace relevante una prueba de resistencia de 18 horas. No se ejecutó esa validación completa por la ventana experimental y el uso de una laptop compartida. Por tanto no se afirma estabilidad de jornada ni ausencia de fugas de memoria.')+p('Se propone aislar servidor y generador, instrumentar base de datos y transacciones, repetir el punto cercano al límite y acordar qué degradación numérica se admite durante campaña.')+p('La entrega conserva escenarios reproducibles, resultados medidos, consumo de recursos y conciliación monetaria. El cumplimiento se informa con evidencia, incluyendo los incumplimientos del sistema original.'),'CIERRE · 13:30–15:00')
 add('Comandos y carpetas para consultar',command('report')+command('open')+p('Ejecuciones completas: usar carga, campana y estres en lugar de report; se ejecutan de una en una. La acción all realiza referencia y los tres perfiles.')+'<pre>tests/performance/escenarios/       → acciones HTTP\ntests/performance/configuracion/   → modelo y umbrales\ntests/performance/resultados/      → evidencia por ejecución\ndocs/parte3/                       → informe\napidoc/parte3/                     → esta presentación</pre>'+p('Para servir presentación y reportes: .venv/Scripts/python.exe -m http.server 8765 --bind 127.0.0.1. Abrir http://localhost:8765/apidoc/parte3/. Ctrl+P permite guardar esta presentación como PDF.'),'ANEXO OPERATIVO')
 add('Anexo / Referencias','<ul><li><a target="_blank" href="https://github.com/granitespinoza/qolqe-g4-qa/tree/parte-3">Repositorio de entrega · tag parte-3</a></li><li><a target="_blank" href="../../tests/performance/resultados/index.html">Reportes y evidencias de Parte 3</a></li><li><a target="_blank" href="../../tests/performance/README.md">Ejecución y decisiones del modelo</a></li><li><a target="_blank" href="../../docs/parte3/Informe_Rendimiento_Qolqe.docx">Informe de rendimiento</a></li><li><a target="_blank" href="https://grafana.com/docs/k6/latest/using-k6/scenarios/">Escenarios de k6</a> · <a target="_blank" href="https://grafana.com/docs/k6/latest/using-k6/thresholds/">Umbrales de k6</a></li></ul>'+p('Base académica: enunciado P2 Parte 3, plantilla docente y semanas 13–14. Los enlaces del repositorio remoto mostrarán esta entrega después de publicar e integrar los cambios. No se declara una ejecución CI de rendimiento que no haya ocurrido.'))
 css='''*{box-sizing:border-box}:root{--ink:#22251f;--sage:#497a6a;--paper:#fafbf9}body{margin:0;background:var(--paper);color:var(--ink);font:20px/1.6 Segoe UI,Arial,sans-serif}header{position:sticky;top:0;z-index:4;background:#fafbf9f5;border-bottom:1px solid #dce2d9;display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:12px 4vw}button,select{font:inherit;font-size:14px;border:1px solid #22251f;background:white;border-radius:7px;padding:8px 12px;cursor:pointer}nav{display:flex;align-items:center;gap:8px}main{max-width:1160px;margin:auto;padding:35px 30px 70px}.slide{padding:38px 48px;border:2px solid #22251f;border-radius:20px;background:white;box-shadow:5px 6px 0 #e9ebe6;min-height:650px}h1{font:500 clamp(30px,4vw,46px)/1.15 Georgia,serif;margin:20px 0 28px}p{margin:18px 0}.label{font-size:13px;letter-spacing:.12em;color:var(--sage);font-weight:700}.lead{font-size:24px;color:var(--sage)}table{width:100%;border-collapse:collapse;font-size:17px;margin:20px 0}td,th{padding:12px;border:1px solid #dce2d9;text-align:left;vertical-align:top}th{background:#ecd9a7}tr:nth-child(even){background:#fafbf9}.scroll{overflow:auto}aside{background:#eef4fa;border-left:4px solid #476f98;padding:20px}a{color:#285e52}img{max-width:100%;height:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.6 Consolas,monospace;background:#edf5f1;padding:20px}.cmd{position:relative}.copy{position:absolute;right:5px;top:5px;padding:3px 8px;font-size:12px}footer{text-align:center;font-size:14px;padding:20px;color:#626861}.all .slide{display:block!important;margin-bottom:30px}body.large{font-size:24px}body.large table{font-size:21px}:fullscreen{overflow:auto;background:#fafbf9}@media(max-width:700px){main{padding:12px}.slide{padding:22px;min-height:0}select{max-width:220px}header{position:static}}@media print{header,footer,.copy{display:none}main{padding:0}.slide,.slide[hidden]{display:block!important;border:0;box-shadow:none;min-height:0;page-break-before:always}body{font-size:16px}h1{font-size:30px}table{font-size:13px}}'''
 js='''const slides=[...document.querySelectorAll('.slide')];let n=0;const jump=document.querySelector('#jump');function show(i){n=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,j)=>s.hidden=j!==n);jump.value=n;document.querySelector('#count').textContent=`${n+1}/${slides.length}`;history.replaceState(null,'','#'+(n+1));scrollTo(0,0)}document.querySelector('#prev').onclick=()=>show(n-1);document.querySelector('#next').onclick=()=>show(n+1);jump.onchange=()=>show(Number(jump.value));document.querySelector('#all').onclick=()=>document.body.classList.toggle('all');document.querySelector('#large').onclick=()=>document.body.classList.toggle('large');document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(n+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(n-1)}});document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.parentElement.querySelector('code').textContent);b.textContent='Copiado'}catch(e){b.textContent='Seleccionar y copiar'}});show(Number(location.hash.slice(1))-1||0);'''
 opt=''.join(f'<option value="{i}">{i+1}. {escape(s[0])}</option>'for i,s in enumerate(slides));body=''.join(f'<section class="slide"{" hidden"if i else""}><div class="label">{s[2]}</div><h1>{s[0]}</h1>{s[1]}</section>'for i,s in enumerate(slides))
 out=ROOT/'apidoc/parte3';out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text('<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quincena Qolqe · Rendimiento</title><style>'+css+'</style></head><body><header><strong>QOLQE / ENTREGA 3</strong><select id="jump" aria-label="Elegir diapositiva">'+opt+'</select><nav><button id="prev" aria-label="Diapositiva anterior">←</button><span id="count"></span><button id="next" aria-label="Diapositiva siguiente">→</button><button id="all">Ver todo</button><button id="large">Letra +</button><button id="full">Pantalla completa</button></nav></header><main>'+body+'</main><footer>Flechas ← → para navegar · Desplazar para leer cada pantalla · Ctrl+P para PDF</footer><script>'+js+'</script></body></html>',encoding='utf-8');print('Presentación:',len(slides),'pantallas')
if __name__=='__main__':main()
